import json
def C(title,scn,prompt,cues,target,en,cando):
    return {"tier":"tier1","level":"B2","title":"Communicative Challenge: "+title,"scenario":scn,"prompt":prompt,"cues":cues,"target":target,"english":en,"canDo":cando}
d={
"b2-puertorico-01":C("What Surprises Visitors","You are Carlos. You and Meg are watching a documentary about El Yunque in Puerto Rico, and she asks what visitors notice most.","Tell Meg what surprises visitors most, putting that idea in the spotlight.",["Say that the amount of rain is what surprises them","Stress that idea"],"Lo que más sorprende a los visitantes es la cantidad de lluvia.","What surprises visitors most is the amount of rain.","I can put one idea in the spotlight with a cleft sentence (*Lo que… es…*, *Fue… cuando…*)."),
"b2-puertorico-02":C("Autonomy Before the War","You are Meg. You and Carlos are reading an article about 1898 in Puerto Rico, and he asks whether Spain had already granted autonomy.","Tell Carlos when Spain granted autonomy, in relation to the war.",["Say that Spain granted autonomy","Say that it was before the war began"],"España concedió la autonomía antes de que empezara la guerra con Estados Unidos.","Spain granted autonomy before the war with the United States began.","I can say that one event happened before or after another with *antes de que* and *después de que*."),
"b2-puertorico-03":C("What Statehood Would Mean","You are Carlos. You and Meg are reading about the options for Puerto Rico's political status, and she asks what one of them would mean.","Describe what one option would mean, without taking sides.",["Name the option","Say what would change for the citizens"],"Si Puerto Rico fuera un estado, sus ciudadanos elegirían senadores con voto.","If Puerto Rico were a state, its citizens would elect senators with a vote.","I can describe what an imagined situation would mean with *si* + imperfect subjunctive and the conditional."),
"b2-puertorico-04":C("Salsa and the Island","You are Meg. You and Carlos are listening to a talk about Puerto Rican music, and he asks whether salsa is from the island.","Tell Carlos that salsa did not begin on the island but Puerto Ricans were important in it.",["Grant the point that it did not begin there","Give the main idea"],"Si bien la salsa no nació en la isla, muchos puertorriqueños fueron figuras importantes.","Although salsa was not born on the island, many Puerto Ricans were important figures in it.","I can grant a true point and then give the main idea with *si bien*."),
"b2-puertorico-05":C("After the Hurricane","You are Carlos. You and Meg are reading an article about Hurricane María, and she asks what the communities did afterwards.","Tell Meg what many communities did and for what purpose.",["Say that communities organised","Say what they did it for"],"Muchas comunidades se organizaron con el fin de repartir agua y comida.","Many communities organised in order to hand out water and food.","I can say what an action is for with *con el fin de*, *con miras a* and *de modo que*."),
"b2-puertorico-consolidation":C("When Was It Protected","You are Meg. After the unit on Puerto Rico, Carlos asks what you remember about El Yunque.","Tell Carlos when El Yunque was protected, putting the date in the spotlight.",["Say that the Spanish crown protected the region","Stress the year"],"Fue en 1876 cuando la corona española protegió esta región.","It was in 1876 that the Spanish crown protected this region.","I can put one idea in the spotlight with a cleft sentence (*Lo que… es…*, *Fue… cuando…*).")}
open('/home/user/parlour-read-a/challenges-puerto-rico.json','w',encoding='utf8').write(json.dumps(d,indent=2,ensure_ascii=False))
